+package oracle.code.onnx.lift;
+
+import oracle.code.onnx.Tensor;
+import oracle.code.onnx.proto.OnnxModel;
+
+import java.io.IOException;
+import java.io.OutputStream;
+import java.lang.foreign.MemorySegment;
+import java.lang.foreign.ValueLayout;
+import java.nio.channels.FileChannel;
+import java.nio.file.Files;
+import java.nio.file.Path;
+import java.util.*;
+import java.util.stream.Collectors;
+
+final class OnnxWeightExporter {
+
+    static final String MODEL_DATA_FILE = "model.onnx_data";
+
+    enum ExportMode {
+        SPLIT,
+        SINGLE;
+
+        static ExportMode parse(String value) {
+            value = value.toLowerCase(Locale.ENGLISH);
+            if (value.startsWith("--weights=")) {
+                value = value.substring("--weights=".length());
+            } else if (value.startsWith("weights=")) {
+                value = value.substring("weights=".length());
+            }
+
+            if (value.equals("single")) {
+                return SINGLE;
+            }
+            return SPLIT;
+        }
+    }
+
+    record WeightLocation(String location, long offset, long length) { }
+
+    static Map<String, WeightLocation> paths(List<OnnxModel.TensorProto> weights, ExportMode mode) {
+        Map<String, WeightLocation> locations = new LinkedHashMap<>();
+        long offset = 0;
+        for (OnnxModel.TensorProto weight : weights) {
+            WeightLocation location = switch (mode) {
+                case SPLIT -> fileLocation(weight);
+                case SINGLE -> {
+                    long length = byteLength(weight);
+                    yield new WeightLocation(MODEL_DATA_FILE, offset, length);
+                }
+            };
+            locations.put(weight.name(), location);
+            offset += mode == ExportMode.SINGLE ? location.length() : 0;
+        }
+        return Map.copyOf(locations);
+    }
+
+    static void exportWeights(List<OnnxModel.TensorProto> weights, Path sourceFolder, Path targetFolder, ExportMode mode) throws IOException {
+        Files.createDirectories(targetFolder);
+        switch (mode) {
+            case SPLIT -> exportWeightFiles(weights, targetFolder);
+            case SINGLE -> exportModelData(weights, sourceFolder, targetFolder.resolve(MODEL_DATA_FILE));
+        }
+    }
+
+    private static WeightLocation fileLocation(OnnxModel.TensorProto weight) {
+        if (weight.externalData() instanceof List<OnnxModel.StringStringEntryProto> externalData) {
+            Map<String, String> map = convertExternalData(externalData);
+            return new WeightLocation(
+                    map.get("location"),
+                    Long.parseLong(map.getOrDefault("offset", "0")),
+                    Long.parseLong(map.getOrDefault("length", "-1")));
+        }
+        return new WeightLocation(OnnxLift.toJavaName(weight.name()), 0L, -1L);
+    }
+
+    private static void exportWeightFiles(List<OnnxModel.TensorProto> weights, Path targetFolder) throws IOException {
+        for (OnnxModel.TensorProto weight : weights) {
+            if (weight.externalData() != null) {
+                continue;
+            }
+            Path weightFile = targetFolder.resolve(OnnxLift.toJavaName(weight.name()));
+            try (OutputStream out = Files.newOutputStream(weightFile)) {
+                writeInlineTensor(weight, out);
+            }
+            IO.println(weightFile + " extracted.");
+        }
+    }
+
+    private static void exportModelData(List<OnnxModel.TensorProto> weights, Path sourceFolder, Path targetFile) throws IOException {
+        try (OutputStream out = Files.newOutputStream(targetFile)) {
+            for (OnnxModel.TensorProto weight : weights) {
+                if (weight.externalData() instanceof List<OnnxModel.StringStringEntryProto> externalData) {
+                    writeExternalTensor(externalData, sourceFolder, out);
+                } else {
+                    writeInlineTensor(weight, out);
+                }
+            }
+        }
+        IO.println(targetFile + " extracted.");
+    }
+
+    private static void writeInlineTensor(OnnxModel.TensorProto weight, OutputStream out) throws IOException {
+        if (weight.floatData() instanceof List<float[]> fd) {
+            for (float[] fa : fd) {
+                out.write(MemorySegment.ofArray(fa).toArray(ValueLayout.JAVA_BYTE));
+            }
+        } else if (weight.int64Data() instanceof List<long[]> ld) {
+            for (long[] la : ld) {
+                out.write(MemorySegment.ofArray(la).toArray(ValueLayout.JAVA_BYTE));
+            }
+        } else if (weight.int32Data() instanceof List<int[]> id) {
+            for (int[] ia : id) {
+                out.write(MemorySegment.ofArray(ia).toArray(ValueLayout.JAVA_BYTE));
+            }
+        } else if (weight.rawData() instanceof byte[] bd) {
+            out.write(bd);
+        } else {
+            throw new UnsupportedOperationException("Unsupported tensor storage for initializer: " + weight.name());
+        }
+    }
+
+    private static void writeExternalTensor(List<OnnxModel.StringStringEntryProto> externalData, Path sourceFolder, OutputStream out) throws IOException {
+        Map<String, String> map = convertExternalData(externalData);
+        Path source = sourceFolder.resolve(map.get("location"));
+        long offset = Long.parseLong(map.getOrDefault("offset", "0"));
+        long length = map.containsKey("length") ? Long.parseLong(map.get("length")) : Files.size(source) - offset;
+        try (FileChannel in = FileChannel.open(source)) {
+            long position = offset;
+            long remaining = length;
+            while (remaining > 0) {
+                long written = in.transferTo(position, remaining, java.nio.channels.Channels.newChannel(out));
+                if (written <= 0) {
+                    throw new IOException("Could not copy external tensor data from " + source);
+                }
+                position += written;
+                remaining -= written;
+            }
+        }
+    }
+
+    static long byteLength(OnnxModel.TensorProto weight) {
+        if (weight.externalData() instanceof List<OnnxModel.StringStringEntryProto> externalData) {
+            Map<String, String> map = convertExternalData(externalData);
+            if (!map.containsKey("length")) {
+                throw new IllegalArgumentException("External initializer '" + weight.name() + "' is missing external_data length");
+            }
+            return Long.parseLong(map.get("length"));
+        }
+        if (weight.rawData() instanceof byte[] bd) {
+            return bd.length;
+        }
+        if (weight.floatData() instanceof List<float[]> fd) {
+            return fd.stream().mapToLong(a -> a.length * ValueLayout.JAVA_FLOAT.byteSize()).sum();
+        }
+        if (weight.int64Data() instanceof List<long[]> ld) {
+            return ld.stream().mapToLong(a -> a.length * ValueLayout.JAVA_LONG.byteSize()).sum();
+        }
+        if (weight.int32Data() instanceof List<int[]> id) {
+            return id.stream().mapToLong(a -> a.length * ValueLayout.JAVA_INT.byteSize()).sum();
+        }
+
+        long elementCount = OnnxLift.joinLongArray(weight.dims()).length != 0
+                ? java.util.Arrays.stream(OnnxLift.joinLongArray(weight.dims())).reduce(1L, Math::multiplyExact)
+                : 1L;
+        return Math.multiplyExact(elementCount, Tensor.ElementType.fromOnnxId(weight.dataType()).bitSize()) / 8L;
+    }
+
+    private static Map<String, String> convertExternalData(List<OnnxModel.StringStringEntryProto> externalData) {
+        return externalData.stream().collect(Collectors.toUnmodifiableMap(OnnxModel.StringStringEntryProto::key, OnnxModel.StringStringEntryProto::value));
+    }
+}
